add_filter( 'user_has_cap', 'perfectpixel_contributors_upload_files', 10, 4 );

function perfectpixel_contributors_upload_files( $allcaps, $caps, $args, $user ) {
	if ( in_array( 'upload_files', $caps, true ) && $user instanceof WP_User && in_array( 'contributor', (array) $user->roles, true ) ) {
		$allcaps['upload_files'] = true;
	}
	return $allcaps;
}
